-- 渠道沙箱验证：Platform 注册数据（2026-10-14 阶段 4 评审稿）
-- 目标库：Platform Support 业务库；手工执行需单独授权，应用启动不会执行。
-- 前置：外部 API 注册数据（requirements/20260914/platform-support-外部API配置与执行/db/platform-support-service/registration-dml.sql）已执行；
--   复用其权限 EXTERNAL_API_READ / EXTERNAL_API_MANAGE 与接入方菜单资源，不新增权限、资源或 Gateway Target。
-- 155 行 INSERT（路由 14、Header 51、Query 6、Guard 84）；0 UPDATE / DELETE；不改表结构。
-- 每条路由的 Header 与 Guard 复制同一 HTTP 方法的公共脚本路由（校验接口复制脚本校验路由），Body 上限 GET 为 0、写入为 65536。
-- 新路由为 DISABLED；激活与外部 API 的 30 条路由同时处理（本目录 local-e2e/activate.sql 只用于本机独立库）。
-- 执行前：把 @plt_ext_operator 设为已批准的真实 Operations 账号 ID；在同一交互连接中执行，不使用 --force。
-- 本文件不含 COMMIT：核对插入行数与 ID（路由 900000000000071031～900000000000071044）后手工 COMMIT，任何不符则 ROLLBACK。
-- 回滚：COMMIT 前 ROLLBACK；COMMIT 后在路由仍为 DISABLED 时按上述 ID 依次删除 Guard、Query、Header、路由。
SET @plt_ext_time=UTC_TIMESTAMP(6);
SET @plt_ext_target=(SELECT target_id FROM t_gateway_target WHERE target_service_code='operations-console-bff' AND channel='OPERATIONS' AND status='ACTIVE');
SELECT @plt_ext_operator operator_id,@plt_ext_target target_id,
  (SELECT COUNT(*) FROM t_permission WHERE permission_id IN (900000000000071101,900000000000071102) AND status='ACTIVE') permissions_2,
  (SELECT COUNT(*) FROM t_gateway_route WHERE route_id BETWEEN 900000000000071031 AND 900000000000071044) existing_routes_0;
-- operator_id、target_id 为空，permissions_2 不为 2，或 existing_routes_0 不为 0 时停止，不进入事务。
START TRANSACTION;





-- 核对插入的 ID 与行数后手工 COMMIT；不符则 ROLLBACK。
